     1	package hotel.reports;
     2	
     3	import hotel.reservations.Reservation;
     4	import hotel.reservations.ReservationStore;
     5	import hotel.rooms.Room;
     6	import hotel.rooms.Rooms;
     7	import java.time.LocalDate;
     8	import java.util.ArrayList;
     9	import java.util.Comparator;
    10	import java.util.List;
    11	
    12	/** Which rooms are occupied on a given night, for the front desk (CSV). */
    13	public final class OccupancyReport {
    14	
    15	    private final Rooms rooms;
    16	    private final ReservationStore store;
    17	
    18	    public OccupancyReport(Rooms rooms, ReservationStore store) {
    19	        this.rooms = rooms;
    20	        this.store = store;
    21	    }
    22	
    23	    public String generate(LocalDate night) {
    24	        List<Reservation> occupying = new ArrayList<>();
    25	        for (Reservation reservation : store.all()) {
    26	            boolean coversNight = !reservation.checkIn().isAfter(night) && reservation.checkOut().isAfter(night);
    27	            if (reservation.isPaid() && coversNight) {
    28	                occupying.add(reservation);
    29	            }
    30	        }
    31	        occupying.sort(Comparator.comparingInt(Reservation::roomNumber));
    32	
    33	        StringBuilder csv = new StringBuilder();
    34	        csv.append("Pousada Maré Alta,occupancy,").append(night).append('\n');
    35	        csv.append("room,type,reservation,check_in,check_out\n");
    36	        for (Reservation reservation : occupying) {
    37	            Room room = rooms.find(reservation.roomNumber()).orElseThrow();
    38	            csv.append(room.number()).append(',')
    39	                    .append(room.type()).append(',')
    40	                    .append(reservation.id()).append(',')
    41	                    .append(reservation.checkIn()).append(',')
    42	                    .append(reservation.checkOut()).append('\n');
    43	        }
    44	        csv.append("total,").append(occupying.size()).append('/').append(rooms.all().size()).append('\n');
    45	        return csv.toString();
    46	    }
    47	}
=== src/main/java/hotel/reports/RatePlanReport.java
     1	package hotel.reports;
     2	
     3	import hotel.reservations.RatePlan;
     4	import hotel.reservations.Reservation;
     5	import hotel.reservations.ReservationStore;
     6	import java.math.BigDecimal;
     7	import java.time.YearMonth;
     8	import java.util.ArrayList;
     9	import java.util.List;
    10	
    11	/** The revenue of the month split by rate plan, for the management (every plan has a line, even with zero). */
    12	public final class RatePlanReport {
    13	
    14	    private final ReservationStore store;
    15	
    16	    public RatePlanReport(ReservationStore store) {
    17	        this.store = store;
    18	    }
    19	
    20	    public String generate(YearMonth month) {
    21	        List<Reservation> withRevenue = new ArrayList<>();
    22	        for (Reservation reservation : store.all()) {
    23	            boolean keptMoney = reservation.amountKept().signum() > 0;
    24	            boolean startsInMonth = YearMonth.from(reservation.checkIn()).equals(month);
    25	            if (keptMoney && startsInMonth) {
    26	                withRevenue.add(reservation);
    27	            }
    28	        }
    29	
    30	        StringBuilder csv = new StringBuilder();
    31	        csv.append("Pousada Maré Alta,rate-plans,").append(month).append('\n');
    32	        csv.append("rate_plan,reservations,amount\n");
    33	        BigDecimal revenue = BigDecimal.ZERO.setScale(2);
    34	        for (RatePlan plan : RatePlan.values()) {
    35	            int count = 0;
    36	            BigDecimal amount = BigDecimal.ZERO.setScale(2);
    37	            for (Reservation reservation : withRevenue) {
    38	                if (reservation.ratePlan() == plan) {
    39	                    count++;
    40	                    amount = amount.add(reservation.amountKept());
    41	                }
    42	            }
    43	            csv.append(plan).append(',').append(count).append(',').append(amount.toPlainString()).append('\n');
    44	            revenue = revenue.add(amount);
    45	        }
    46	        csv.append("total,").append(withRevenue.size()).append(',').append(revenue.toPlainString()).append('\n');
    47	        return csv.toString();
    48	    }
    49	}
