   159	            ctx.json(new ErrorResponse(exception.errorCode().name(), exception.getMessage()));
   160	        });
   161	    }
   162	
   163	    private static int httpStatus(ErrorCode errorCode) {
   164	        return switch (errorCode) {
   165	            case INVALID_REQUEST -> 400;
   166	            case ROOM_NOT_FOUND, RESERVATION_NOT_FOUND -> 404;
   167	            case ROOM_UNAVAILABLE, OPERATION_NOT_ALLOWED -> 409;
   168	            case CAPACITY_EXCEEDED -> 422;
   169	        };
   170	    }
   171	
   172	    private static NewReservation readNewReservation(Context ctx) {
   173	        CreateReservationRequest body;
   174	        try {
   175	            body = ctx.bodyAsClass(CreateReservationRequest.class);
   176	        } catch (Exception unreadableBody) { // Jackson's own exceptions are checked, but reach here unwrapped
   177	            throw new HotelException(ErrorCode.INVALID_REQUEST, "the body is not a valid reservation request");
   178	        }
   179	        if (body == null
   180	                || body.roomNumber() == null
   181	                || isBlank(body.guestName())
   182	                || isBlank(body.guestEmail())
   183	                || isBlank(body.guestCpf())
   184	                || body.checkIn() == null
   185	                || body.checkOut() == null
   186	                || body.guests() == null
   187	                || body.ratePlan() == null) {
   188	            throw new HotelException(ErrorCode.INVALID_REQUEST, "every field of the reservation is required");
   189	        }
   190	        Guest guest = new Guest(body.guestName(), body.guestEmail(), body.guestCpf());
   191	        return new NewReservation(
   192	                body.roomNumber(), guest, body.checkIn(), body.checkOut(), body.guests(), body.ratePlan());
   193	    }
   194	
   195	    private static long reservationId(Context ctx) {
   196	        String id = ctx.pathParam("id");
   197	        try {
   198	            return Long.parseLong(id);
   199	        } catch (NumberFormatException notANumber) {
   200	            throw new HotelException(ErrorCode.RESERVATION_NOT_FOUND, "reservation " + id + " does not exist");
   201	        }
   202	    }
   203	
   204	    private static LocalDate readDate(Context ctx) {
   205	        String date = requiredQueryParam(ctx, "date");
   206	        try {
   207	            return LocalDate.parse(date);
   208	        } catch (DateTimeParseException badDate) {
   209	            throw new HotelException(ErrorCode.INVALID_REQUEST, "'" + date + "' is not a date (yyyy-MM-dd)");
   210	        }
   211	    }
   212	
   213	    private static YearMonth readMonth(Context ctx) {
   214	        String month = requiredQueryParam(ctx, "month");
   215	        try {
   216	            return YearMonth.parse(month);
   217	        } catch (DateTimeParseException badMonth) {
   218	            throw new HotelException(ErrorCode.INVALID_REQUEST, "'" + month + "' is not a month (yyyy-MM)");
   219	        }
   220	    }
   221	
   222	    private static String requiredQueryParam(Context ctx, String name) {
   223	        String value = ctx.queryParam(name);
   224	        if (value == null) {
   225	            throw new HotelException(ErrorCode.INVALID_REQUEST, "the query parameter '" + name + "' is required");
   226	        }
   227	        return value;
   228	    }
   229	
   230	    private static boolean isBlank(String text) {
   231	        return text == null || text.isBlank();
   232	    }
   233	}
